<?php

declare(strict_types=1);

namespace DoctrineMigrations;

/** Les valeurs initiales du solde, gelées avec la migration plutôt que l’image applicative. */
final class GameBalanceSeed
{
    private const string DATA = "";

    /** @return array<string, mixed> */
    public static function data(): array
    {
        $json = base64_decode(self::DATA, true);
        $data = json_decode($json ?: throw new \LogicException(), true, 512, JSON_THROW_ON_ERROR);
        if (!is_array($data)) {
            throw new \LogicException();
        }

        return $data;
    }
}
